import names from '../../data/country_names.json';
import type { Lang, Localized } from './types';
import { LOCALE_TAGS } from './i18n';

/**
 * Country names in every language (data/country_names.json, generated by
 * scripts/build-country-names.ts). Client-safe: a static JSON import.
 */
const NAMES = names as Record<string, Localized>;

export function countryNames(iso3: string): Localized {
  const n = NAMES[iso3];
  if (!n) throw new Error(`no localized names for ${iso3}`);
  return n;
}

export function countryName(iso3: string, lang: Lang): string {
  return countryNames(iso3)[lang];
}

export interface CountryOption {
  iso3: string;
  name: string;
  flag: string;
}

/** Country choices for menus, named and alphabetized in the player's language. */
export function countryOptions(factors: { iso3: string; flag: string }[], lang: Lang): CountryOption[] {
  const collator = new Intl.Collator(LOCALE_TAGS[lang]);
  return factors
    .map((c) => ({ iso3: c.iso3, name: countryName(c.iso3, lang), flag: c.flag }))
    .sort((a, b) => collator.compare(a.name, b.name));
}
